function obterRotaAtiva(
  rotaAtual: string
): string {
  if (
    rotaAtual === 'AdicionarRepertorio' ||
    rotaAtual === 'DetalheRepertorio' ||
    rotaAtual === 'VisualizarArquivo'
  ) {
    return 'Repertorios';
  }

  if (
    rotaAtual === 'DetalhesEscala'
  ) {
    return 'Escalas';
  }

  return rotaAtual;
}

/*
 * Monta o contorno da navbar com um recorte em "U" no topo,
 * deixando o espaço do ícone selecionado realmente vazado
 * (em vez de uma sombra sobreposta à cor de fundo).
 */
function construirContornoComRecorte({
  largura,
  altura,
  raioCanto,
  centroRecorte,
  larguraRecorte,
  profundidadeRecorte,
  desenharRecorte,
}: {
  largura: number;
  altura: number;
  raioCanto: number;
  centroRecorte: number;
  larguraRecorte: number;
  profundidadeRecorte: number;
  desenharRecorte: boolean;
}) {
  // Ícones das pontas ficariam com o recorte espremido/desalinhado contra o
  // canto arredondado; nesse caso a barra fica lisa, sem "U", nessa posição.
  if (!desenharRecorte) {
    return `
      M ${raioCanto} 0
      H ${largura - raioCanto}
      A ${raioCanto} ${raioCanto} 0 0 1 ${largura} ${raioCanto}
      V ${altura - raioCanto}
      A ${raioCanto} ${raioCanto} 0 0 1 ${largura - raioCanto} ${altura}
      H ${raioCanto}
      A ${raioCanto} ${raioCanto} 0 0 1 0 ${altura - raioCanto}
      V ${raioCanto}
      A ${raioCanto} ${raioCanto} 0 0 1 ${raioCanto} 0
      Z
    `;
  }

  const raioRecorte = larguraRecorte / 2;
  // Mantém o recorte com a mesma largura/forma em toda a barra, mesmo perto
  // das bordas, para não distorcer o "U" nem invadir os ícones vizinhos.
  const margemLateral = raioCanto + raioRecorte + 10;
  const centro = Math.min(
    largura - margemLateral,
    Math.max(margemLateral, centroRecorte)
  );
  const inicioRecorte = centro - raioRecorte;
  const fimRecorte = centro + raioRecorte;

  // Semicírculo justo (corda = diâmetro), abraçando o ícone sem fundo reto.
  return `
    M ${raioCanto} 0
    H ${inicioRecorte}
    A ${raioRecorte} ${raioRecorte} 0 0 0 ${fimRecorte} 0
    H ${largura - raioCanto}
    A ${raioCanto} ${raioCanto} 0 0 1 ${largura} ${raioCanto}
    V ${altura - raioCanto}
    A ${raioCanto} ${raioCanto} 0 0 1 ${largura - raioCanto} ${altura}
    H ${raioCanto}
    A ${raioCanto} ${raioCanto} 0 0 1 0 ${altura - raioCanto}
    V ${raioCanto}
    A ${raioCanto} ${raioCanto} 0 0 1 ${raioCanto} 0
    Z
  `;
}

function BotaoNavbar({
  item,
  selecionado,
  onPress,
}: {
  item: ItemNavbar;
  selecionado: boolean;
  onPress: () => void;
}) {
  const animacao = useRef(
    new Animated.Value(
      selecionado ? 1 : 0
    )
  ).current;
  const pulsoSelecao = useRef(
    new Animated.Value(
      selecionado ? 1 : 0
    )
  ).current;

  useEffect(() => {
    Animated.spring(
      animacao,
      {
        toValue: selecionado ? 1 : 0,
        friction: 7,
        tension: 85,
        useNativeDriver: true,
      }
    ).start();

    if (selecionado) {
      pulsoSelecao.setValue(0);
      Animated.sequence([
        Animated.timing(pulsoSelecao, {
          toValue: 1,
          duration: 180,
          useNativeDriver: true,
        }),
        Animated.spring(pulsoSelecao, {
          toValue: 0.82,
          friction: 4,
          tension: 90,
          useNativeDriver: true,
        }),
      ]).start();
    } else {
      pulsoSelecao.setValue(0);
    }
  }, [
    animacao,
    pulsoSelecao,
    selecionado,
  ]);

  const translateY =
    animacao.interpolate({
      inputRange: [0, 1],
      outputRange: [0, -8],
    });

  const scale =
    animacao.interpolate({
      inputRange: [0, 1],
      outputRange: [1, 1],
    });

  const legendaTranslateY =
    animacao.interpolate({
      inputRange: [0, 1],
      outputRange: [4, 0],
    });

  const escalaIcone =
    pulsoSelecao.interpolate({
      inputRange: [0, 0.82, 1],
      outputRange: [1, 1.08, 1.14],
    });

  return (
    <TouchableOpacity
      style={[
        estilos.itemNavbar,
        selecionado &&
          estilos.itemNavbarSelecionado,
      ]}
      onPress={onPress}
      activeOpacity={0.8}
      accessibilityLabel={
        item.titulo
      }
    >
      <Animated.View
        style={[
          estilos.circuloIcone,

          selecionado
            ? estilos.circuloSelecionado
            : estilos.circuloNormal,

          {
            backgroundColor:
              selecionado
                ? item.corFundo
                : 'rgba(255,255,255,0.08)',

            borderColor:
              selecionado
                ? item.corBorda
                : 'rgba(255,255,255,0.17)',

            shadowColor:
              item.corFundo,
          },

          {
            transform: [
              {
                translateY,
              },
              {
                scale,
              },
            ],
          },
        ]}
      >
        {selecionado && (
          <View
            style={
              estilos.haloSelecionado
            }
          />
        )}

        {selecionado && (
          <View
            pointerEvents="none"
            style={
              estilos.reflexoSelecionado
            }
          />
        )}

        <Animated.View
          style={{
            transform: [
              { scale: escalaIcone },
            ],
          }}
        >
          <MaterialCommunityIcons
            name={item.icone}
            size={selecionado ? 20 : 20}
            color={
              selecionado
                ? item.corIcone
                : item.corFundo
            }
          />
        </Animated.View>
      </Animated.View>

      {selecionado && (
        <Animated.Text
          numberOfLines={1}
          style={[
            estilos.legendaSelecionada,
            {
              opacity: animacao,
              transform: [
                {
                  translateY:
                    legendaTranslateY,
                },
              ],
            },
          ]}
        >
          {item.titulo}
        </Animated.Text>
      )}
    </TouchableOpacity>
  );
}

function BarraNavegacaoFixa({
  rotaAtual,
  onNavigate,
}: {
  rotaAtual: string;
  onNavigate: (
    rota: string
  ) => void;
}) {
  const rotaAtiva =
    obterRotaAtiva(
      rotaAtual || ''
    );

  const indiceAtivo = Math.max(
    0,
    ITENS_NAVBAR.findIndex(
      (item) => item.rota === rotaAtiva
    )
  );

  // Largura real da navbar, medida via onLayout (responsiva/maxWidth 520).
  const [larguraBarra, setLarguraBarra] = useState(320);

  const calcularCentroPixel = (indice: number) =>
    ((indice + 0.5) / ITENS_NAVBAR.length) * larguraBarra;

  // Segue o indice ativo com uma mola, em vez de "pular" instantaneamente.
  const indiceAnimado = useRef(
    new Animated.Value(indiceAtivo)
  ).current;
  const [centroRecorte, setCentroRecorte] = useState(
    calcularCentroPixel(indiceAtivo)
  );

  useEffect(() => {
    const idListener = indiceAnimado.addListener(({ value }) => {
      setCentroRecorte(calcularCentroPixel(value));
    });
    return () => indiceAnimado.removeListener(idListener);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [indiceAnimado, larguraBarra]);

  useEffect(() => {
    Animated.spring(indiceAnimado, {
      toValue: indiceAtivo,
      friction: 8,
      tension: 70,
      useNativeDriver: false,
    }).start();
  }, [indiceAnimado, indiceAtivo]);

  if (
    !rotaAtual ||
    rotaAtual === 'SplashLogo'
  ) {
    return null;
  }

  const contornoComRecorte = construirContornoComRecorte({
    largura: larguraBarra,
    altura: ALTURA_NAVBAR,
    raioCanto: 22,
    centroRecorte,
    larguraRecorte: 60,
    profundidadeRecorte: 38,
    // Nas pontas o recorte ficaria espremido contra o canto arredondado.
    desenharRecorte:
      indiceAtivo > 0 &&
      indiceAtivo < ITENS_NAVBAR.length - 1,
  });

  const navbar = (
    <View
      style={[
        estilos.areaNavbar,
        POSICAO_FIXA_WEB,
      ]}
      pointerEvents="box-none"
    >
      <View
        onLayout={(evento) =>
          setLarguraBarra(evento.nativeEvent.layout.width)
        }
        style={
          estilos.navbar
        }
      >
        <Svg
          width="100%"
          height={ALTURA_NAVBAR}
          viewBox={`0 0 ${larguraBarra} ${ALTURA_NAVBAR}`}
          style={StyleSheet.absoluteFill}
          pointerEvents="none"
        >
          <Defs>
            <SvgLinearGradient id="fundoNavbar" x1="0" y1="0" x2="1" y2="1">
              <Stop offset="0" stopColor="#264767" stopOpacity={0.88} />
              <Stop offset="0.5" stopColor="#0C213B" stopOpacity={0.84} />
              <Stop offset="1" stopColor="#040F20" stopOpacity={0.94} />
            </SvgLinearGradient>
          </Defs>
          <Path
            d={contornoComRecorte}
            fill="url(#fundoNavbar)"
            stroke="rgba(175,233,255,0.34)"
            strokeWidth={1}
          />
        </Svg>

        <View
          pointerEvents="none"
          style={
            estilos.vidroReflexo
          }
        />

        <View
          pointerEvents="none"
          style={
            estilos.vidroBrilhoLateral
          }
        />

        <View
          style={
            estilos.luzSuperior
          }
        />

        <View
          style={
            estilos.listaNavbar
          }
        >
          {ITENS_NAVBAR.map(
            (item) => (
              <BotaoNavbar
                key={
                  item.rota
                }
                item={
                  item
                }
                selecionado={
                  item.rota ===
                  rotaAtiva
                }
                onPress={() =>
                  onNavigate(
                    item.rota
                  )
                }
              />
            )
          )}
        </View>
      </View>
    </View>
  );

  /*
   * Mantém a navbar fora dos contêineres com rolagem,
   * preservando a posição fixa no PWA.
   */
  if (
    Platform.OS === 'web' &&
    typeof document !== 'undefined'
  ) {
    return createPortal(
      navbar,
      document.body
    );
  }

  return navbar;
}

export default function AppNavigator(): JSX.Element {
  const [
    rotaAtual,
    setRotaAtual,
  ] = useState(
    'SplashLogo'
  );

  const navegacaoStack =
    useRef<any>(
      null
    );

  const exibirNavbar =
    rotaAtual !==
    'SplashLogo';

  function navegarPelaNavbar(
    rota: string
  ) {
    if (
      rota === rotaAtual
    ) {
      return;
    }

    navegacaoStack.current?.navigate(
      rota
    );
  }

  return (
    <View
      style={
        estilos.containerPrincipal
      }
    >
      <View
        style={[
          estilos.areaConteudo,

          /*
           * A splash continua ocupando a tela inteira.
           *
           * Nas demais telas, reservamos apenas a altura
           * necessária para a navbar.
           */
          exibirNavbar &&
            estilos.areaConteudoComNavbar,
        ]}
      >
        <Stack.Navigator
          initialRouteName="SplashLogo"
          screenOptions={{
            headerShown: false,

            cardStyle: {
              backgroundColor:
                '#071426',
            },
          }}
          screenListeners={({
            navigation,
            route,
          }) => ({
            focus: () => {
              navegacaoStack.current =
                navigation;

              setRotaAtual(
                route.name
              );
            },
          })}
        >
          <Stack.Screen
            name="SplashLogo"
            component={
              SplashLogoScreen
            }
          />

          <Stack.Screen
            name="Inicio"
            component={
              TelaInicio
            }
          />

          <Stack.Screen
            name="CriarEscala"
            component={
              TelaCriarEscala
            }
          />

          <Stack.Screen
            name="Escalas"
            component={
              TelaListaEscalas
            }
          />

          <Stack.Screen
            name="DetalhesEscala"
            component={
              TelaDetalhesEscala
            }
          />

          <Stack.Screen
            name="Repertorios"
            component={
              RepertoiresScreen
            }
          />

          <Stack.Screen
            name="AdicionarRepertorio"
            component={
              AdicionarRepertorio
            }
          />

          <Stack.Screen
            name="DetalheRepertorio"
            component={
              DetalheRepertorio
            }
          />

          <Stack.Screen
            name="VisualizarArquivo"
            component={
              VisualizarArquivo
            }
          />

          <Stack.Screen
            name="Presenca"
            component={
              PresencaScreen
            }
          />

          <Stack.Screen
            name="Interacao"
            component={
              InteracaoScreen
            }
          />

          <Stack.Screen
            name="Avisos"
            component={
              AvisosScreen
            }
          />

          <Stack.Screen
            name="Ensaios"
            component={
              EnsaiosScreen
            }
          />

          <Stack.Screen
            name="Aniversariantes"
            component={
              TelaAniversariantes
            }
          />

          <Stack.Screen
            name="Agenda"
            component={
              TelaAgenda
            }
          />

          <Stack.Screen
            name="Estatisticas"
            component={
              TelaEstatisticas
            }
          />
        </Stack.Navigator>
      </View>

      <BarraNavegacaoFixa
        rotaAtual={
          rotaAtual
        }
        onNavigate={
          navegarPelaNavbar
        }
      />
    </View>
  );
}

